public class MicrosoftDemanglerAnalyzerTest : AbstractGhidraHeadedIntegrationTest {

	private ProgramDB program;
	private MicrosoftDemanglerAnalyzer analyzer = new MicrosoftDemanglerAnalyzer();

	private MessageLog log = new _Anon_MessageLog_1();

	/* @Before */
	public void setUp()
    {

		ProgramBuilder builder = new ToyProgramBuilder("test", true);
		builder.createMemory(".text", "0x0100", 0x100);
		program = builder.getProgram();
		registerOptions();
	}

	/* @Override */
	protected void testFailed(Throwable e) {
		Msg.error(this, "Test failed - analysis log:\n" + log);
	}

	/* @Test */
	public void testOptions__ApplyFunctionSignature()
    {

		string mangled = "?InvokeHelperV@COleDispatchDriver@@QAEXJGGPAXPBEPAD@Z";

		Address addr = addr("0x110");
		createSymbol(addr, mangled);

		setApplySignatureOption(true);

		analyze();

		FunctionManager fm = program.getFunctionManager();
		Function function = fm.getFunctionAt(addr);
		assertNotNull(function);
		assertTrue("Funciton signature not applied", function.getParameterCount() > 0);
	}

	/* @Test */
	public void testOptions__DoNotApplyFunctionSignature()
    {

		string mangled = "?InvokeHelperV@COleDispatchDriver@@QAEXJGGPAXPBEPAD@Z";

		Address addr = addr("0x110");
		createSymbol(addr, mangled);

		setApplySignatureOption(false);

		analyze();

		FunctionManager fm = program.getFunctionManager();
		Function function = fm.getFunctionAt(addr);
		assertNotNull(function);
		assertEquals("undefined InvokeHelperV(void)", function.getSignature().toString());
	}

	/* @Test */
	public void testApplyComplicatedFunctionSignatureHavingReference()
    {

		string mangled = "?f2@@YAP6AP6AHH@ZP6ADD@Z@ZAAP6AP6AHH@Z0@Z@Z";

		Address addr = addr("0x110");
		createSymbol(addr, mangled);

		analyze();

		FunctionManager fm = program.getFunctionManager();
		Function function = fm.getFunctionAt(addr);
		assertNotNull(function);
		ParameterDefinition[] @params = function.getSignature().getArguments();
		assertEquals(1, @params.length);
		ParameterDefinition param = @params[0];
		assertEquals("_func__func_int_int_ptr__func_char_char_ptr * * param_1",
			param.toString());
		assertEquals(
			"_func__func_int_int_ptr__func_char_char_ptr * f2(_func__func_int_int_ptr__func_char_char_ptr * * param_1)",
			function.getSignature().toString());
	}

//==================================================================================================
// Private Methods
//==================================================================================================

	private void analyze() {
		tx(program, () => analyzer.added(program, program.getMemory(), TaskMonitor.DUMMY, log));
	}

	private void setApplySignatureOption(bool doUse) {

		// Analyzers . Demangler Microsoft . msdApplyOptions . applyFunctionSignatures

		Options analyzerOptions = program.getOptions(
			"Analyzers" + Options.DELIMITER_STRING + MicrosoftDemanglerAnalyzer.NAME);

		MsdApplyOption applyOption =
			(MsdApplyOption) analyzerOptions
					.getCustomOption(MicrosoftDemanglerAnalyzer.APPLY_OPTIONS_LABEL, null);

		tx(program, () => {
			applyOption.setApplySignature(doUse);
		});
		analyzer.optionsChanged(analyzerOptions, program);
	}

	private void registerOptions() {
		Options options = program.getOptions(Program.ANALYSIS_PROPERTIES);
		Options analyzerOptions = options.getOptions(analyzer.getName());
		analyzer.registerOptions(analyzerOptions, program);
	}

	private void createSymbol(Address addr, string mangled) {
		AddLabelCmd cmd = new AddLabelCmd(addr, mangled, SourceType.ANALYSIS);
		applyCmd(program, cmd);
	}

	private Address addr(string addr) {
		return program.getAddressFactory().getAddress(addr);
	}

	internal class _Anon_MessageLog_1 : MessageLog
	{


		// overridden to prevent stack traces from appearing in the console
		/* @Override */
		public void appendException(Throwable t) {
			appendMsg(t.toString());
		}
	
	}

}
